import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const T=JSON.parse('{"title":"2018-Jun-13 :: Ceph Testing Weekly","description":"","frontmatter":{"title":"2018-Jun-13 :: Ceph Testing Weekly","date":"2018-06-19T00:00:00.000Z","updated":"2018-06-20T00:00:00.000Z","tags":["Ceph 测试","Tautology","Ceph RGW","Ceph 安全仪表板","Redmine"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Jun-13_-_-_Ceph_Testing_Weekly.md","filePath":"posts/2018/2018-Jun-13_-_-_Ceph_Testing_Weekly.md","lastUpdated":1780459816000}'),n={name:"posts/2018/2018-Jun-13_-_-_Ceph_Testing_Weekly.md"};function s(p,l,a,u,g,r){return t(),e("div",null,[...l[0]||(l[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 多位Ceph社区成员，包括Zach、Greg、Rick、Ally、Tatiana、Yuri等。</p><p><strong>会议主题</strong>：</p><ul><li>检查上次会议的行动项完成情况</li><li>讨论Ceph测试框架Tautology的改进和扩展</li><li>探索使用Libcloud进行测试的可能性</li><li>讨论Ceph RGW功能测试的改进</li><li>讨论Ceph安全仪表板的测试</li></ul><p><strong>关键细节</strong>：</p><ul><li><strong>上次会议行动项</strong>： <ul><li>红帽工程师创建的Redmine工单尚未创建。</li><li>需要更多PR以便进行审查和测试。</li><li>需要为Tautology编写开发指南文档。</li><li>需要为Tautology集成测试环境编写Ansible脚本。</li></ul></li><li><strong>Tautology改进</strong>： <ul><li>讨论了将Asuza的OpenStack后端补丁合并到Tautology中，并使用Libcloud进行测试。</li><li>讨论了使用Tautology进行测试时的节点分配问题。</li><li>讨论了为Tautology编写文档，以帮助开发者编写任务。</li><li>讨论了将Tautology部署到Jenkins以进行测试。</li></ul></li><li><strong>Ceph RGW功能测试</strong>： <ul><li>讨论了使用Tautology对RGW进行测试，包括S3测试和RGW管理员套件测试。</li><li>讨论了为RGW测试编写Ansible脚本。</li><li>讨论了使用Tautology进行升级测试，例如将Ceph集群从Luminous升级到Mimic。</li></ul></li><li><strong>Ceph安全仪表板的测试</strong>： <ul><li>Tatiana介绍了Red Hat的Ceph安全仪表板（Set Metrics），并讨论了如何对其进行测试。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>红帽工程师将继续创建Redmine工单。</li><li>红帽工程师将审查和合并更多PR。</li><li>红帽工程师将为Tautology编写开发指南文档。</li><li>红帽工程师将为Tautology集成测试环境编写Ansible脚本。</li><li>红帽工程师将与社区成员合作，改进和扩展Tautology。</li><li>红帽工程师将使用Tautology进行Ceph RGW功能测试和升级测试。</li><li>红帽工程师将探索使用Libcloud进行测试的可能性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>红帽工程师将在下次会议之前完成上述行动项。</li><li>红帽工程师将参加RGW站立会议，讨论Ceph RGW功能测试的改进。</li><li>红帽工程师将与社区成员合作，改进和扩展Tautology。</li></ul><p><strong>其他</strong>：</p><ul><li>会议中讨论了一些其他话题，例如Ceph社区会议的安排和Ceph安全仪表板的开发。</li><li>会议结束时，红帽工程师将整理会议纪要并发送给参会人员。</li></ul>",13)])])}const d=i(n,[["render",s]]);export{T as __pageData,d as default};
